L = function(D, w0, w1) {
  return D.reduce( (res, e) =&gt;
    res - [e.y * Math.log(sigmoid(w0+w1*e.x)) + (1-e.y) * Math.log(1-sigmoid(w0+w1*e.x))], 0
  ) / D.length;
}
