mutable leaf = null;
gini = {
  if(!leaf)
    return '';
  const tree = JSON.parse(JSON.stringify(treeB));
  const l = findNode(tree, leaf.id);
  const lastId = leaves(tree).map(d =&gt; d.id).reduce((a, b) =&gt; (a &gt; b ? a : b));
  const left = {
    id: lastId + 1,
    parent: l.id,
    type: "leaf"
  };
  const right = {
    id:  lastId + 2,
    parent: l.id,
    type: "leaf"
  }
  Object.assign(l, {
      type: "split",
      feature: feature,
      value: t,
      name: `${feature} ≤ ${t}`,
      left: left,
      right: right
  });
  const left_count = Object.values(getCount(tree, left, iris));
  const right_count = Object.values(getCount(tree, right, iris));
  const left_n = left_count.reduce((accumulator, currentValue) =&gt; accumulator + currentValue, 0);
  const right_n = right_count.reduce((accumulator, currentValue) =&gt; accumulator + currentValue, 0);
  const left_gini = 1-left_count.reduce((accumulator, currentValue) =&gt; accumulator + (currentValue/left_n * currentValue/left_n), 0);
  const right_gini = 1-right_count.reduce((accumulator, currentValue) =&gt; accumulator + (currentValue/right_n * currentValue/right_n), 0);
  const n = left_n + right_n;
  const gini = (left_n/n) * left_gini + (right_n/n) * right_gini;
  return gini;
}
