function dataAtNode(tree, node, data) {
    const res = [];
    if(tree.id === node.id)
      return data;
    if(tree.type === 'leaf')
      return [];
    const leftData = data.filter((d) =&gt; d[tree.feature] &lt;=  tree.value);
    const rightData = data.filter((d) =&gt; d[tree.feature] &gt;  tree.value);
    res.push(...dataAtNode(tree.left, node, leftData));
    res.push(...dataAtNode(tree.right, node, rightData));
    return res;
}
function regionAtLeaf(tree, node, rect) {
    if(!node)
      return {x1: -Infinity, x2: Infinity, y1: -Infinity, y2: Infinity};
    if(tree.type === 'leaf' && tree.id === node.id)
      return rect;
    if(tree.type === 'leaf')
      return {x1: -Infinity, x2: Infinity, y1: -Infinity, y2: Infinity};
    const left = regionAtLeaf(tree.left, node, {
      x1: rect.x1,
      x2: tree.feature === 'petalLength' ? tree.value : rect.x2,
      y1: rect.y1,
      y2: tree.feature === 'petalWidth' ? tree.value : rect.y2,
    });
    const right = regionAtLeaf(tree.right, node, {
      x2: rect.x2,
      x1: tree.feature === 'petalLength' ? tree.value : rect.x1,
      y2: rect.y2,
      y1: tree.feature === 'petalWidth' ? tree.value : rect.y1,
    });
    return {
      x1: Math.max(left.x1, right.x1),
      x2: Math.min(left.x2, right.x2),
      y1: Math.max(left.y1, right.y1),
      y2: Math.min(left.y2, right.y2)
    };
}
















