boundaryData = function(tree, features=['x_1', 'x_2'], predict=false, data=null) {
  const gridSize = 80;
  const grid = [];
  for (let i = 0; i &lt; gridSize; i++) {
      for (let j = 0; j &lt; gridSize; j++) {
        const x =  (i / gridSize) * 8;
        const y = -1 + (j / gridSize) * 4;
        const p = {};
        p[features[0]] = x; p[features[1]] = y;
        const node = findLeaf(tree, p);
        let label = node.label;
        if(predict) {
          const count = getCount(tree, node, data);
          label = Object.keys(count).reduce((a, b) =&gt; {
            return count[a] &gt; count[b] ? a : b;
          });
        }
        grid.push({ x, y, label });
      }
  }
  return grid;
}
