function findKNN(point, allData, k) {
  return allData
    .filter(d =&gt; d.id !== point.id)
    .map(d =&gt; ({ ...d, dist: distance(point, d) }))
    .sort((a, b) =&gt; a.dist - b.dist)
    .slice(0, k);
}
















